import { act, render } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import {
  createRef,
  useEffect,
  useLayoutEffect,
  useRef,
  type PropsWithChildren,
  type RefObject
} from "react";
import { beforeEach, describe, expect, test, vi } from "vitest";
import { subscribeToMountedGroup } from "../../global/mutable-state/groups";
import { moveSeparator } from "../../global/test/moveSeparator";
import { assert } from "../../utils/assert";
import {
  setDefaultElementBounds,
  setElementBoundsFunction
} from "../../utils/test/mockBoundingClientRect";
import { Panel } from "../panel/Panel";
import type { PanelImperativeHandle } from "../panel/types";
import { Separator } from "../separator/Separator";
import { Group } from "./Group";
import type { GroupImperativeHandle, Layout } from "./types";
import { useGroupRef } from "./useGroupRef";

describe("Group", () => {
  test("changes to defaultProps or disableCursor should not cause Group to remount", () => {
    const onChange = vi.fn();
    const removeListener = subscribeToMountedGroup("group", onChange);

    const { rerender } = render(
      <Group
        defaultLayout={{
          a: 50,
          b: 50
        }}
        disableCursor={false}
        id="group"
      >
        <Panel id="a" />
        <Panel id="b" />
      </Group>
    );
    expect(onChange).toHaveBeenCalled();

    onChange.mockReset();

    rerender(
      <Group
        defaultLayout={{
          a: 35,
          b: 65
        }}
        disableCursor={true}
        id="group"
      >
        <Panel id="a" />
        <Panel id="b" />
      </Group>
    );
    expect(onChange).not.toHaveBeenCalled();

    removeListener();
  });

  test("should support updates to either Group or Panel ids", () => {
    const { rerender } = render(
      <Group id="a">
        <Panel id="a-a" />
        <Panel id="a-b" />
      </Group>
    );

    rerender(
      <Group id="a">
        <Panel id="b-a" />
        <Panel id="b-b" />
      </Group>
    );

    rerender(
      <Group id="b">
        <Panel id="b-a" />
        <Panel id="b-b" />
      </Group>
    );

    rerender(
      <Group id="c">
        <Panel id="c-a" />
        <Panel id="c-b" />
      </Group>
    );
  });

  describe("in-memory layout cache", () => {
    async function runTest(
      callback: (args: {
        container: HTMLElement;
        groupRef: RefObject<GroupImperativeHandle | null>;
        panelRef: RefObject<PanelImperativeHandle | null>;
      }) => Promise<void>,
      expectedLayout: Layout,
      // `true` when the callback simulates a direct separator manipulation —
      // a pointer drag or a keyboard resize (see #716); `false` for imperative
      // API / mount which fall under the "library-driven" bucket of the flag.
      expectedIsUserInteraction: boolean
    ) {
      setElementBoundsFunction((element) => {
        switch (element.id) {
          case "group": {
            return new DOMRect(0, 0, 100, 50);
          }
          case "left": {
            return new DOMRect(0, 0, 50, 50);
          }
          case "right": {
